Local Ltac transport_chunks segs m a bs ::= transport_chunks_n8 segs m a bs; try transport_cond_ro segs m a bs.
Local Ltac addr_diff E A ::=
  lazymatch A with
  | E => constr:(0%Z)
  | _ =>
    match E with
    | Z.add ?X ?c1 =>
        let c1 := zlit c1 in
        lazymatch A with
        | Z.add X ?c2 => let c2 := zlit c2 in eval vm_compute in (c1 - c2)%Z
        | X => c1
        | _ => let e := zlit E in let a := zlit A in let d := eval vm_compute in (e - a)%Z in
               lazymatch eval vm_compute in (andb (Z.leb 0 d) (Z.ltb d 4096))%Z with true => d end
        end
    | _ =>
        lazymatch A with
        | Z.add E ?c2 => let c2 := zlit c2 in eval vm_compute in (- c2)%Z
        | _ => let e := zlit E in let a := zlit A in let d := eval vm_compute in (e - a)%Z in
               lazymatch eval vm_compute in (andb (Z.leb 0 d) (Z.ltb d 4096))%Z with true => d end
        end
    end
  end.
